;WITH SourceRows AS
(
    SELECT
        tenant,
        bucket_id,
        object_path,
        content_type,
        bytes_length,
        sha256_hex,
        created_at,
        updated_at,
        data_hex
    FROM OPENJSON(@DemoObjects)
    WITH
    (
        tenant NVARCHAR(255) '$.tenant',
        bucket_id VARCHAR(50) '$.bucket_id',
        object_path NVARCHAR(500) '$.object_path',
        content_type NVARCHAR(255) '$.content_type',
        bytes_length BIGINT '$.bytes_length',
        sha256_hex CHAR(64) '$.sha256_hex',
        created_at DATETIME2 '$.created_at',
        updated_at DATETIME2 '$.updated_at',
        data_hex NVARCHAR(MAX) '$.data_hex'
    )
)
MERGE crm.objects AS target
USING SourceRows AS source
    ON target.tenant = source.tenant
   AND target.bucket_id = source.bucket_id
   AND target.object_path = source.object_path
WHEN MATCHED THEN
    UPDATE SET
        content_type = source.content_type,
        bytes_length = source.bytes_length,
        sha256_hex = source.sha256_hex,
        created_at = source.created_at,
        updated_at = source.updated_at,
        data = CONVERT(VARBINARY(MAX), source.data_hex, 2)
WHEN NOT MATCHED BY TARGET THEN
    INSERT
    (
        tenant,
        bucket_id,
        object_path,
        content_type,
        bytes_length,
        sha256_hex,
        created_at,
        updated_at,
        data
    )
    VALUES
    (
        source.tenant,
        source.bucket_id,
        source.object_path,
        source.content_type,
        source.bytes_length,
        source.sha256_hex,
        source.created_at,
        source.updated_at,
        CONVERT(VARBINARY(MAX), source.data_hex, 2)
    );
